import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";

import * as AspectRatio from "../../ui/aspect-ratio";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const imageSrc = "https://avatar.vercel.sh/shadcn1";

export const view = Submodel.defineView<Model, Message>(
  (): Html =>
    AspectRatio.view<Message>({
      ratio: 9 / 16,
      src: imageSrc,
      alt: "Photo",
    })
);

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeApplication({
  Model,
  init,
  update,
  view: (model) => ({
    title: "Aspect Ratio Portrait",
    body: view(model),
  }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import { init, update, view } from "./main";

describe("aspect-ratio-portrait example", () => {
  test("renders the shadcn portrait image example", () => {
    const [model] = init();

    Scene.scene(
      { update, view },
      Scene.with(model),
      Scene.expect(Scene.role("img", { name: "Photo" })).toExist(),
      Scene.expect(Scene.role("img", { name: "Photo" })).toHaveAttr(
        "src",
        "https://avatar.vercel.sh/shadcn1"
      ),
      Scene.expect(Scene.role("img", { name: "Photo" })).not.toHaveHandler(
        "click"
      )
    );
  });
});
